package org.apache.commons.cli;

import java.io.*;
import java.io.PrintWriter;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.Iterator;
import java.util.List;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class HelpFormatter_findWrapPos_TriageGen1Test {

    private final HelpFormatter formatter = new HelpFormatter();

    @Test
    public void testWrapPosWithNewlineBeforeWidth() {
        String text = "This is a test\nwith a newline";
        int width = 10;
        int startPos = 0;
        int expected = 11;
        assertEquals(expected, formatter.findWrapPos(text, width, startPos));
    }

    @Test
    public void testWrapPosWithTabBeforeWidth() {
        String text = "This is a test\twith a tab";
        int width = 10;
        int startPos = 0;
        int expected = 11;
        assertEquals(expected, formatter.findWrapPos(text, width, startPos));
    }

    @Test
    public void testWrapPosWithNewlineAfterWidth() {
        String text = "This is a test\nwith a newline";
        int width = 20;
        int startPos = 0;
        int expected = 20;
        assertEquals(expected, formatter.findWrapPos(text, width, startPos));
    }

    @Test
    public void testWrapPosWithTabAfterWidth() {
        String text = "This is a test\twith a tab";
        int width = 20;
        int startPos = 0;
        int expected = 20;
        assertEquals(expected, formatter.findWrapPos(text, width, startPos));
    }

    @Test
    public void testWrapPosWithWhitespaceBeforeWidth() {
        String text = "This is a test with spaces";
        int width = 10;
        int startPos = 0;
        int expected = 10;
        assertEquals(expected, formatter.findWrapPos(text, width, startPos));
    }

    @Test
    public void testWrapPosNoWhitespaceBeforeWidth() {
        String text = "ThisIsATestWithoutSpaces";
        int width = 10;
        int startPos = 0;
        int expected = 10;
        assertEquals(expected, formatter.findWrapPos(text, width, startPos));
    }

    @Test
    public void testWrapPosAtEndOfText() {
        String text = "Short";
        int width = 10;
        int startPos = 0;
        int expected = -1;
        assertEquals(expected, formatter.findWrapPos(text, width, startPos));
    }

    @Test
    public void testWrapPosBeyondEndOfText() {
        String text = "Short";
        int width = 10;
        int startPos = 3;
        int expected = -1;
        assertEquals(expected, formatter.findWrapPos(text, width, startPos));
    }

    @Test
    public void testWrapPosExactWidth() {
        String text = "ExactWidthTest";
        int width = 12;
        int startPos = 0;
        int expected = 12;
        assertEquals(expected, formatter.findWrapPos(text, width, startPos));
    }

    @Test
    public void testWrapPosStartBeyondWidth() {
        String text = "StartBeyondWidth";
        int width = 5;
        int startPos = 10;
        int expected = 15;
        assertEquals(expected, formatter.findWrapPos(text, width, startPos));
    }

    @Test
    public void testWrapPosEmptyText() {
        String text = "";
        int width = 10;
        int startPos = 0;
        int expected = -1;
        assertEquals(expected, formatter.findWrapPos(text, width, startPos));
    }

    @Test
    public void testWrapPosNegativeStartPos() {
        String text = "NegativeStartPos";
        int width = 10;
        int startPos = -5;
        int expected = 5;
        assertEquals(expected, formatter.findWrapPos(text, width, startPos));
    }
}
